CREATE OR REPLACE FUNCTION public.registrar_senal_cambio_sesion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_usuario_id uuid;
BEGIN

    IF TG_TABLE_SCHEMA = 'public'
       AND TG_TABLE_NAME = 'usuarios' THEN

        v_usuario_id := NEW.id;

    ELSIF TG_TABLE_SCHEMA = 'public'
       AND TG_TABLE_NAME = 'administraciones_temporales' THEN

        IF TG_OP = 'DELETE' THEN
            v_usuario_id := OLD.usuario_id;

        ELSIF TG_OP = 'UPDATE' THEN

            -- No avisar por cambios que no afectan permisos.
            IF NEW.usuario_id IS NOT DISTINCT FROM OLD.usuario_id
               AND NEW.vigente_desde IS NOT DISTINCT FROM OLD.vigente_desde
               AND NEW.vigente_hasta IS NOT DISTINCT FROM OLD.vigente_hasta
               AND NEW.revocado_at IS NOT DISTINCT FROM OLD.revocado_at
            THEN
                RETURN NEW;
            END IF;

            -- Si excepcionalmente cambia el destinatario,
            -- avisar también al usuario anterior.
            IF NEW.usuario_id IS DISTINCT FROM OLD.usuario_id THEN

                INSERT INTO public.usuarios_sesion_cambios (
                    usuario_id, revision, actualizado_en
                )
                VALUES (
                    OLD.usuario_id,
                    1,
                    pg_catalog.clock_timestamp()
                )
                ON CONFLICT (usuario_id)
                DO UPDATE SET
                    revision =
                        public.usuarios_sesion_cambios.revision + 1,
                    actualizado_en =
                        pg_catalog.clock_timestamp();

            END IF;

            v_usuario_id := NEW.usuario_id;

        ELSE
            v_usuario_id := NEW.usuario_id;
        END IF;

    ELSE
        RAISE EXCEPTION
            'Trigger ejecutado desde una tabla no autorizada.';
    END IF;

    -- Generar o incrementar la señal.
    INSERT INTO public.usuarios_sesion_cambios (
        usuario_id, revision, actualizado_en
    )
    VALUES (
        v_usuario_id,
        1,
        pg_catalog.clock_timestamp()
    )
    ON CONFLICT (usuario_id)
    DO UPDATE SET
        revision =
            public.usuarios_sesion_cambios.revision + 1,
        actualizado_en =
            pg_catalog.clock_timestamp();

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.usuario_eliminacion_preparar_v1(p_objetivo_id uuid, p_nombre_exacto text, p_motivo text, p_confirmacion boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_actor_id uuid;
    v_actor_nombre text;

    v_objetivo_nombre text;
    v_objetivo_rol uuid;
    v_objetivo_estado boolean;

    v_administradores integer;
    v_archivos integer;

    v_operacion_id uuid;
    v_existente
        public.usuarios_eliminaciones_operaciones%ROWTYPE;

    v_resumen jsonb;
BEGIN

    -- 1. Validar la identidad real.
    v_actor_id := auth.uid();

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'SESION_REQUERIDA';
    END IF;

    IF NOT public.es_administrador_permanente_actual()
    THEN
        RAISE EXCEPTION
            'ADMINISTRADOR_PERMANENTE_REQUERIDO';
    END IF;

    SELECT NULLIF(btrim(u.nombre), '')
    INTO v_actor_nombre
    FROM public.usuarios u
    WHERE u.id = v_actor_id
      AND u.estado IS TRUE;

    IF v_actor_nombre IS NULL THEN
        RAISE EXCEPTION
            'IDENTIDAD_ADMINISTRADOR_INCOMPLETA';
    END IF;

    -- 2. Validar parámetros.
    IF p_objetivo_id IS NULL THEN
        RAISE EXCEPTION 'USUARIO_OBJETIVO_REQUERIDO';
    END IF;

    IF p_objetivo_id = v_actor_id THEN
        RAISE EXCEPTION 'AUTOELIMINACION_PROHIBIDA';
    END IF;

    IF p_confirmacion IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'CONFIRMACION_REQUERIDA';
    END IF;

    IF p_nombre_exacto IS NULL
       OR btrim(p_nombre_exacto) = ''
    THEN
        RAISE EXCEPTION 'NOMBRE_EXACTO_REQUERIDO';
    END IF;

    IF p_motivo IS NULL
       OR length(p_motivo) NOT BETWEEN 10 AND 1000
       OR p_motivo <> btrim(p_motivo)
    THEN
        RAISE EXCEPTION 'MOTIVO_INVALIDO';
    END IF;

    -- 3. Confirmar existencia en Auth.
    IF NOT EXISTS (
        SELECT 1
        FROM auth.users a
        WHERE a.id = p_objetivo_id
    ) THEN
        RAISE EXCEPTION 'CUENTA_AUTH_NO_EXISTE';
    END IF;

    -- 4. Bloquear el perfil durante la preparación.
    SELECT
        NULLIF(btrim(u.nombre), ''),
        u.rol_id,
        u.estado
    INTO
        v_objetivo_nombre,
        v_objetivo_rol,
        v_objetivo_estado
    FROM public.usuarios u
    WHERE u.id = p_objetivo_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PERFIL_NO_EXISTE';
    END IF;

    IF v_objetivo_nombre IS NULL THEN
        RAISE EXCEPTION 'NOMBRE_OBJETIVO_INCOMPLETO';
    END IF;

    -- Comparación exacta, sin normalizar.
    IF p_nombre_exacto IS DISTINCT FROM v_objetivo_nombre
    THEN
        RAISE EXCEPTION 'NOMBRE_NO_COINCIDE';
    END IF;

    -- 5. Proteger al último administrador.
    IF v_objetivo_estado IS TRUE
       AND v_objetivo_rol IS NOT NULL
       AND public.es_rol_administrador(
           v_objetivo_rol
       )
    THEN

        SELECT COUNT(*)
        INTO v_administradores
        FROM public.usuarios u
        WHERE u.estado IS TRUE
          AND public.es_rol_administrador(u.rol_id);

        IF v_administradores <= 1 THEN
            RAISE EXCEPTION
                'ULTIMO_ADMINISTRADOR_PROTEGIDO';
        END IF;

    END IF;

    -- 6. Bloquear cuentas con objetos Storage.
    SELECT COUNT(*)
    INTO v_archivos
    FROM storage.objects o
    WHERE o.owner_id = p_objetivo_id::text
       OR o.owner = p_objetivo_id;

    IF v_archivos > 0 THEN
        RAISE EXCEPTION
            'STORAGE_REQUIERE_REVISION';
    END IF;

    -- 7. Bloquear asignaciones activas.
    IF EXISTS (
        SELECT 1
        FROM public.mantenciones m
        WHERE m.responsable_id = p_objetivo_id
    ) THEN
        RAISE EXCEPTION
            'MANTENCIONES_ASIGNADAS_REQUIEREN_REVISION';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.tareas t
        WHERE t.responsable_id = p_objetivo_id
    ) THEN
        RAISE EXCEPTION
            'TAREAS_ASIGNADAS_REQUIEREN_REVISION';
    END IF;

    -- 8. Documentar las dependencias conocidas.
    -- Los conteos no certifican aún la
    -- conservación histórica integral.
    v_resumen := jsonb_build_object(

        'solicitudes_creadas',
        (
            SELECT COUNT(*)
            FROM public.solicitudes_reactivas s
            WHERE s.creada_por = p_objetivo_id
        ),

        'avisos_asociados',
        (
            SELECT COUNT(*)
            FROM public.solicitudes_reactivas_avisos a
            WHERE EXISTS (
                SELECT 1
                FROM public.solicitudes_reactivas s
                WHERE s.id = a.solicitud_id
                  AND s.creada_por = p_objetivo_id
            )
        ),

        'documentos_trabajadores',
        (
            SELECT COUNT(*)
            FROM public.trabajadores_documentos d
            WHERE d.creado_por = p_objetivo_id
        ),

        'documentos_prevencionista',
        (
            SELECT COUNT(*)
            FROM public.prevencion_documentos d
            WHERE d.creado_por = p_objetivo_id
        ),

        'archivos_storage',
        v_archivos,

        'conservacion_historica_certificada',
        false,

        'procedimiento_preparacion',
        'USUARIO_ELIMINACION_PREPARAR_V1'
    );

    -- 9. Crear operación, respetando el índice
    -- único de operaciones activas.
    INSERT INTO public.usuarios_eliminaciones_operaciones (
        objetivo_id,
        objetivo_nombre_snapshot,
        actor_id,
        actor_nombre_snapshot,
        motivo,
        estado,
        dependencias_resumen
    )
    VALUES (
        p_objetivo_id,
        v_objetivo_nombre,
        v_actor_id,
        v_actor_nombre,
        p_motivo,
        'PREPARADA',
        v_resumen
    )
    ON CONFLICT (objetivo_id)
    WHERE estado IN (
        'PREPARADA',
        'AUTH_EN_CURSO',
        'AUTH_ELIMINADA',
        'REQUIERE_REVISION'
    )
    DO NOTHING
    RETURNING id INTO v_operacion_id;

    -- 10. Resolver solicitudes repetidas.
    IF v_operacion_id IS NULL THEN

        SELECT *
        INTO v_existente
        FROM public.usuarios_eliminaciones_operaciones
        WHERE objetivo_id = p_objetivo_id
          AND estado IN (
              'PREPARADA',
              'AUTH_EN_CURSO',
              'AUTH_ELIMINADA',
              'REQUIERE_REVISION'
          )
        FOR UPDATE;

        IF FOUND
           AND v_existente.estado = 'PREPARADA'
           AND v_existente.actor_id = v_actor_id
           AND v_existente.motivo = p_motivo
           AND v_existente.objetivo_nombre_snapshot
               = v_objetivo_nombre
        THEN
            RETURN jsonb_build_object(
                'resultado', 'YA_PREPARADA',
                'operacion_id', v_existente.id,
                'estado', v_existente.estado,
                'eliminacion_habilitada', false
            );
        END IF;

        RAISE EXCEPTION
            'OPERACION_EXISTENTE_REQUIERE_REVISION';

    END IF;

    -- 11. No habilitar eliminación real.
    RETURN jsonb_build_object(
        'resultado', 'PREPARADA',
        'operacion_id', v_operacion_id,
        'estado', 'PREPARADA',
        'eliminacion_habilitada', false,
        'dependencias_resumen', v_resumen
    );

END;
$function$

CREATE OR REPLACE FUNCTION public.usuario_eliminacion_registrar_resultado_auth_v1(p_operacion_id uuid, p_resultado text, p_error_codigo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_operacion
        public.usuarios_eliminaciones_operaciones%ROWTYPE;

    v_codigo text;
BEGIN
    -- 1. Validar argumentos.
    IF p_operacion_id IS NULL THEN
        RAISE EXCEPTION 'OPERACION_ID_REQUERIDO';
    END IF;

    IF p_resultado IS NULL
       OR p_resultado NOT IN ('CONFIRMADA', 'INCIERTA')
    THEN
        RAISE EXCEPTION 'RESULTADO_AUTH_INVALIDO';
    END IF;

    -- 2. Bloquear la operación para evitar
    -- actualizaciones simultáneas.
    SELECT *
    INTO v_operacion
    FROM public.usuarios_eliminaciones_operaciones
    WHERE id = p_operacion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'OPERACION_NO_ENCONTRADA';
    END IF;

    -- 3. Permitir consultar nuevamente un
    -- resultado confirmado, sin modificarlo.
    IF v_operacion.estado = 'AUTH_ELIMINADA'
       AND p_resultado = 'CONFIRMADA'
       AND v_operacion.dependencias_resumen
           @> '{"auth_eliminacion_verificada":true}'::jsonb
    THEN
        RETURN jsonb_build_object(
            'resultado', 'YA_CONFIRMADA',
            'operacion_id', v_operacion.id,
            'estado', v_operacion.estado
        );
    END IF;

    -- 4. No aceptar resultados Auth si la
    -- eliminación no fue iniciada formalmente.
    IF v_operacion.estado <> 'AUTH_EN_CURSO' THEN
        RAISE EXCEPTION
            'ESTADO_NO_PERMITE_REGISTRAR_AUTH';
    END IF;

    -- 5. Registrar un resultado incierto
    -- sin repetir ninguna eliminación.
    IF p_resultado = 'INCIERTA' THEN

        v_codigo := COALESCE(
            p_error_codigo,
            'RESULTADO_AUTH_INCIERTO'
        );

        -- Guardar solo códigos controlados,
        -- nunca textos libres con secretos.
        IF v_codigo !~
           '^[A-Z][A-Z0-9_]{2,79}$'
        THEN
            RAISE EXCEPTION
                'CODIGO_ERROR_INVALIDO';
        END IF;

        UPDATE public.usuarios_eliminaciones_operaciones
        SET
            estado = 'REQUIERE_REVISION',
            ultimo_error_codigo = v_codigo,
            updated_at = clock_timestamp()
        WHERE id = v_operacion.id;

        RETURN jsonb_build_object(
            'resultado', 'REQUIERE_REVISION',
            'operacion_id', v_operacion.id,
            'estado', 'REQUIERE_REVISION'
        );

    END IF;

    -- 6. Para confirmar Auth, exigir que
    -- la ejecución estuviera autorizada.
    IF NOT (
        v_operacion.dependencias_resumen
        @> '{"conservacion_historica_certificada":true}'::jsonb
    ) THEN
        RAISE EXCEPTION
            'CONSERVACION_HISTORICA_NO_CERTIFICADA';
    END IF;

    IF NOT (
        v_operacion.dependencias_resumen
        @> '{"autorizacion_irreversible_confirmada":true}'::jsonb
    ) THEN
        RAISE EXCEPTION
            'AUTORIZACION_IRREVERSIBLE_PENDIENTE';
    END IF;

    IF v_operacion.intentos_auth < 1 THEN
        RAISE EXCEPTION
            'INTENTO_AUTH_NO_REGISTRADO';
    END IF;

    -- 7. Verificar la ausencia de la cuenta.
    IF EXISTS (
        SELECT 1
        FROM auth.users
        WHERE id = v_operacion.objetivo_id
    ) THEN
        RAISE EXCEPTION
            'CUENTA_AUTH_TODAVIA_EXISTE';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.usuarios
        WHERE id = v_operacion.objetivo_id
    ) THEN
        RAISE EXCEPTION
            'PERFIL_USUARIO_TODAVIA_EXISTE';
    END IF;

    -- 8. Registrar la verificación
    -- y actualizar el estado conjuntamente.
    UPDATE public.usuarios_eliminaciones_operaciones
    SET
        estado = 'AUTH_ELIMINADA',

        dependencias_resumen =
            dependencias_resumen
            || jsonb_build_object(
                'auth_eliminacion_verificada', true,
                'auth_verificada_en',
                    clock_timestamp()
            ),

        ultimo_error_codigo = NULL,
        updated_at = clock_timestamp()

    WHERE id = v_operacion.id;

    RETURN jsonb_build_object(
        'resultado', 'AUTH_ELIMINADA',
        'operacion_id', v_operacion.id,
        'estado', 'AUTH_ELIMINADA'
    );

END;
$function$
